import{_ as o,o as i,c,a0 as d}from"./chunks/framework.DqMqoJl9.js";const m=JSON.parse('{"title":"VueUse","description":"","frontmatter":{},"headers":[],"relativePath":"vue/vueuse.md","filePath":"vue/vueuse.md","lastUpdated":1791573371000}'),l={name:"vue/vueuse.md"};function r(t,e,a,s,p,u){return i(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="vueuse" tabindex="-1">VueUse <a class="header-anchor" href="#vueuse" aria-label="Permalink to &quot;VueUse&quot;">​</a></h1><h2 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h2><ul><li><p><code>createGlobalState</code> 将状态保留在全局范围内，小号 Pinia</p></li><li><p><code>createInjectionState</code> 创建可注入到组件中的全局状态</p></li><li><p><code>createSharedComposable</code> 创建一个可在多个 Vue 实例中使用的组合式函数</p></li><li><p><code>injectLocal</code> 扩展了 inject 的功能，使其能够调用 provideLocal 在同一组件中提供值</p></li><li><p><code>provideLocal</code> 扩展 provide 功能，可调用 injectLocal 获取同一组件中的值</p></li><li><p><code>useAsyncState</code> 响应式异步状态。不会阻塞你的设置函数，并在 Promise 准备好后触发变化。状态默认为 shallowRef</p></li><li><p><code>useLastChanged</code> 记录 ref 最后更改的时间戳</p></li><li><p><code>useRefHistory</code> 追踪 ref 的变化历史，同时提供撤销和重做功能</p></li><li><p><code>useDebouncedRefHistory</code> useRefHistory 的简写，带防抖过滤</p></li><li><p><code>useThrottledRefHistory</code> useRefHistory 的节流过滤简写</p></li><li><p><code>useManualRefHistory</code> 在使用时手动跟踪 ref 的变化历史，同时提供撤销和重做功能</p></li><li><p><code>useStorage</code> 创建一个可用来访问和修改 LocalStorage 或 SessionStorage 的响应式 ref</p></li><li><p><code>useLocalStorage</code> 响应式 LocalStorage</p></li><li><p><code>useSessionStorage</code> 响应式 SessionStorage</p></li><li><p><code>useStorageAsync</code> 支持异步的响应式 Storage</p></li></ul><h2 id="elements" tabindex="-1">Elements <a class="header-anchor" href="#elements" aria-label="Permalink to &quot;Elements&quot;">​</a></h2><ul><li><p><code>useElementBounding</code> 获取元素宽高位置信息</p></li><li><p><code>useElementSize</code> 获取元素大小，ResizeObserver</p></li><li><p><code>useElementVisibility</code> 追踪元素在视口内的可见性</p></li><li><p><code>useIntersectionObserver</code> 检测目标元素的可见性</p></li><li><p><code>useMouseInElement</code> 与元素相关的鼠标位置</p></li><li><p><code>useParentElement</code> 获取元素的父级</p></li><li><p><code>useMutationObserver</code> 监视 DOM 树的变化</p></li><li><p><code>useResizeObserver</code> 监听元素大小变化</p></li><li><p><code>useActiveElement</code> 获取当前 active 激活的元素，响应式 document.activeElement</p></li><li><p><code>useDraggable</code> 使元素可拖动</p></li><li><p><code>useDropZone</code> 创建一个可以放置文件的区域（将文件从电脑拖放到放置区域）</p></li><li><p><code>useDocumentVisibility</code> 获取当前页面的可见状态，最小化页面或切换标签页，响应式追踪 document.visibilityState</p></li><li><p><code>useWindowFocus</code> 监听当前页面聚焦状态</p></li><li><p><code>useWindowScroll</code> 监听窗口滚动</p></li><li><p><code>useWindowSize</code> 监听窗口大小</p></li></ul><h2 id="browser" tabindex="-1">Browser <a class="header-anchor" href="#browser" aria-label="Permalink to &quot;Browser&quot;">​</a></h2><ul><li><p><code>useEventListener</code> 轻松使用 EventListener。在 mounted 时使用 addEventListener 进行注册，并在 unmounted 时自动移除</p></li><li><p><code>useImage</code> 响应式加载图片，可以等待结果再显示或者显示一个备用方案</p></li><li><p><code>useFileDialog</code> 打开文件对话框，选择文件</p></li><li><p><code>useFileSystemAccess</code> 创建、读取和写入本地文件，<code>系统 API FileSystemAccess</code></p></li><li><p><code>useClipboard</code> 剪贴板，可以异步地从系统剪贴板读取和写，<code>系统 API Clipboard</code></p></li><li><p><code>useClipboardItems</code> useClipboard 是一个纯文本函数，而 useClipboardItems 是基于 ClipboardItem 的函数。可以使用 useClipboardItems 来复制任何 ClipboardItem 支持的内容</p></li><li><p><code>useMediaControls</code> 控制和获取媒体数据</p></li><li><p><code>useObjectUrl</code> 通过 URL.createObjectURL() 为提供的 File、Blob 或 MediaSource 创建 URL</p></li><li><p><code>useBrowserLocation</code> 解析并监听当前 URL，如果使用了 VueRouter 使用 useRoute</p></li><li><p><code>useScriptTag</code> 创建一个脚本标签，支持在卸载时自动卸载该脚本标签</p></li><li><p><code>useTextDirection</code> 文字方向，ltr rtl</p></li><li><p><code>useUrlSearchParams</code> 响应式 URLSearchParams</p></li><li><p><code>useTextareaAutosize</code> 根据内容自动更新文本区域的高度</p></li><li><p><code>useFullscreen</code> 为特定元素提供全屏显示的方法，<code>系统 API Fullscreen</code></p></li><li><p><code>useTitle</code> 设置页面标题</p></li><li><p><code>useFavicon</code> 更改 favicon</p></li><li><p><code>usePreferredLanguages</code> 获取用户首选语言，<code>系统 API Navigator.languages</code></p></li><li><p><code>usePermission</code> 获取当前浏览器权限，<code>系统 API Permissions</code></p></li><li><p><code>useScreenOrientation</code> 获取屏幕方向，<code>系统 API Screen Orientation</code></p></li><li><p><code>useStyleTag</code> 在头部注入响应式 style 元素</p></li><li><p><code>useCssVar</code> 操作 CSS 变量</p></li><li><p><code>useBreakpoints</code> 这个指 viewport breakpoints（可自定义 sm md lg xl 等）</p></li><li><p><code>useColorMode</code> 更改颜色主题</p></li><li><p><code>useDark</code> 主题更改为暗夜模式</p></li><li><p><code>usePreferredDark</code> 当前系统主题是否是暗夜</p></li><li><p><code>usePreferredColorScheme</code> 获取系统主题颜色，<code>系统 API prefers-color-scheme</code></p></li><li><p><code>useEyeDropper</code> 拾色器工具，<code>系统 API EyeDropper</code></p></li><li><p><code>useMediaQuery</code> 媒体查询，获取当前屏幕大小等</p></li><li><p><code>useMemory</code> 获取当前页面内存信息，<code>系统 API Performance.memory</code></p></li><li><p><code>usePerformanceObserver</code> 观察性能指标，<code>系统 API PerformanceObserver</code></p></li><li><p><code>usePreferredContrast</code> 检测用户是否要求以更低或更高的对比度来呈现 Web 内容</p></li><li><p><code>usePreferredReducedMotion</code> 检测用户的系统是否被开启了动画减弱功能，<code>系统 API prefers-reduced-motion</code></p></li><li><p><code>usePreferredReducedTransparency</code> 检测用户是否在其设备上启用了减少设备上使用的透明或半透明层效果的设置，<code>prefers-reduced-transparency</code></p></li><li><p><code>usePreferredContrast</code> 获取对比度，<code>系统 API prefers-contrast</code></p></li><li><p><code>useScreenSafeArea</code> 获取屏幕能完全展示的区域（针对一些异形屏）</p></li><li><p><code>useSSRWidth</code> 置一个全局视口宽度，当渲染依赖视口宽度的 SSR 组件（如 useMediaQuery 或 useBreakpoints ）时将使用该宽度</p></li><li><p><code>useShare</code> 分享，<code>系统 API Navigator.share()</code></p></li><li><p><code>useWakeLock</code> 屏幕唤醒锁，可保持屏幕唤醒，<code>系统 API Screen Wake Lock</code></p></li><li><p><code>useWebNotification</code> 桌面通知，<code>系统 API Notification</code></p></li><li><p><code>useWebWorker</code> 简单的 Web Workers 注册和通信，在后台线程中运行脚本，<code>系统 API Web Workers</code></p></li><li><p><code>useWebWorkerFn</code> alewin/useWorker 的一个接口</p></li><li><p><code>useBroadcastChannel</code> 同源的不同浏览器窗口、标签页、frame 或者 iframe 下的不同文档之间相互通信，<code>系统 API BroadcastChannel</code></p></li><li><p><code>useBluetooth</code> 提供连接和与蓝牙低功耗外设交互的能力，<code>系统 API Web Bluetooth</code></p></li><li><p><code>useGamepad</code> 游戏手柄，<code>系统 API Gamepad</code></p></li><li><p><code>useVibrate</code> 振动硬件，<code>系统 API Vibration</code></p></li></ul><h2 id="sensors" tabindex="-1">Sensors <a class="header-anchor" href="#sensors" aria-label="Permalink to &quot;Sensors&quot;">​</a></h2><ul><li><p><code>onClickOutside</code> 监听元素外部的点击</p></li><li><p><code>onLongPress</code> 监听元素上的长按事件</p></li><li><p><code>onStartTyping</code> 监听输入，在不可编辑的元素上开始输入时触发</p></li><li><p><code>onKeyStroke</code> 监听键盘按键事件</p></li><li><p><code>useElementHover</code> 获取元素 hover 状态</p></li><li><p><code>useFocus</code> 获取或设置 focus 状态</p></li><li><p><code>useFocusWithin</code> 跟踪一个元素或其子元素是否获得焦点，它旨在匹配 <code>:focus-within</code> CSS 伪类的行为</p></li><li><p><code>useKeyModifier</code> 获取修饰键的状态，例如 shift 是否按住</p></li><li><p><code>useMagicKeys</code> 获取所有按键状态</p></li><li><p><code>useMouse</code> 鼠标指针位置</p></li><li><p><code>useMousePressed</code> 鼠标按下状态</p></li><li><p><code>usePageLeave</code> 鼠标是否离开页面</p></li><li><p><code>usePointer</code> 获取指针状态，<code>系统 API Pointer events</code></p></li><li><p><code>usePointerLock</code> 指针锁定（隐藏指针？）</p></li><li><p><code>useScroll</code> 响应式滚动位置和状态</p></li><li><p><code>useScrollLock</code> 锁定元素滚动</p></li><li><p><code>onElementRemoval</code> 监听元素被移除</p></li><li><p><code>usePointerSwipe</code> 基于 PointerEvents 的滑动检测</p></li><li><p><code>useSwipe</code> 基于 TouchEvents 的响应式滑动检测</p></li><li><p><code>useElementByPoint</code> 获取某个坐标指向的元素</p></li><li><p><code>useInfiniteScroll</code> 无限滚动（虚拟滚动条）</p></li><li><p><code>useNavigatorLanguage</code> navigator.language</p></li><li><p><code>useTextSelection</code> 基于 Window.getSelection 追踪用户文本选择（获取选中的文本）</p></li><li><p><code>useDevicePixelRatio</code> 获取设备像素比，<code>window.devicePixelRatio</code></p></li><li><p><code>useIdle</code> 追踪用户是否处于非活动状态（当前页面）</p></li><li><p><code>useNetwork</code> 网络状态，<code>系统 API Network Information</code></p></li><li><p><code>useOnline</code> 在线状态，useNetwork 的包装器</p></li><li><p><code>useFps</code> 获取当前帧数</p></li><li><p><code>useGeolocation</code> 获取位置信息，<code>系统 API Geolocation</code></p></li><li><p><code>useDeviceMotion</code> 获取设备位置和方向变化速度信息，<code>DeviceMotionEvent</code></p></li><li><p><code>useDeviceOrientation</code> 获取设备的物理方向的信息，<code>DeviceOrientationEvent</code></p></li><li><p><code>useBattery</code> 获取电池信息充放电状态等，<code>系统 API Battery Status</code></p></li><li><p><code>useDevicesList</code> 获取可用的输入/输出设备，相机麦克风扬声器等，<code>MediaDevices enumerateDevices()</code></p></li><li><p><code>useDisplayMedia</code> 录屏，可以用于共享屏幕，<code>mediaDevices.getDisplayMedia</code></p></li><li><p><code>useUserMedia</code> 用户摄像头媒体的流式传输（可用于视频会议或直播？），<code>系统 API mediaDevices.getUserMedia</code></p></li><li><p><code>useParallax</code> 创建视差效果，它使用 useDeviceOrientation</p></li><li><p><code>useSpeechRecognition</code> 语音识别，<code>系统 API SpeechRecognition</code></p></li><li><p><code>useSpeechSynthesis</code> 语音合成，<code>系统 API SpeechSynthesis</code></p></li></ul><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><ul><li><code>useEventSource</code> EventSource 与 HTTP 服务器建立持久连接，<code>系统 API EventSource</code></li><li><code>useFetch</code> Fetch</li><li><code>useWebSocket</code> WebSocket</li></ul><h2 id="animation" tabindex="-1">Animation <a class="header-anchor" href="#animation" aria-label="Permalink to &quot;Animation&quot;">​</a></h2><ul><li><code>useInterval</code> 计数器，提供 counter, reset, pause, resume</li><li><code>useIntervalFn</code> 带有控制功能的 setInterval 包装器</li><li><code>useTimeout</code> 在一定时间后更新值，并带有控制功能</li><li><code>useTimeoutFn</code> 带有控制选项的 setTimeout 函数的封装</li><li><code>useNow</code> 响应式当前日期</li><li><code>useTimestamp</code> 响应式的当前时间戳</li><li><code>useRafFn</code> 在每次 requestAnimationFrame 上调用函数。具有暂停和恢复控制</li><li><code>useAnimate</code> 动画 <code>系统 API Web Animations</code></li><li><code>useTransition</code> 值之间的过渡效果</li></ul><h2 id="component" tabindex="-1">Component <a class="header-anchor" href="#component" aria-label="Permalink to &quot;Component&quot;">​</a></h2><ul><li><code>useVirtualList</code> 虚拟列表</li><li><code>computedInject</code> 结合 computed 和 inject 使用</li><li><code>createReusableTemplate</code> 在组件作用域内定义和重用模板</li><li><code>createTemplatePromise</code> 将模板作为 Promise。适用于构建自定义对话框、模态框、提示框等</li><li><code>templateRef</code> 将 ref 绑定到模板元素的简写方式</li><li><code>unrefElement</code> 从 ref 或 Vue 组件实例中检索基础 DOM 元素</li><li><code>useCurrentElement</code> 将当前组件的 DOM 元素作为 ref 返回</li><li><code>useTemplateRefsList</code> 将 refs 绑定到 v-for 内的模板元素和组件的快捷方式</li><li><code>useMounted</code> 获取组件是否已挂载</li><li><code>useVModel</code> v-model 绑定的简写，推荐用 defineModel</li><li><code>useVModels</code> props 的 v-model 绑定的简写方式</li><li><code>tryOnBeforeMount</code> 安全的 onBeforeMount。如果在组件生命周期内，调用 onBeforeMount()，如果不是，直接调用函数</li><li><code>tryOnBeforeUnmount</code> 安全的 onBeforeUnmount。如果在组件生命周期内，调用 onBeforeUnmount()，如果不是，不执行任何操作</li><li><code>tryOnMounted</code> 安全的 onMounted。如果在组件生命周期内，调用 onMounted()，如果不是，直接调用函数</li><li><code>tryOnScopeDispose</code> 安全的 onScopeDispose。如果在效果范围生命周期内，调用 onScopeDispose()，如果不是，不执行任何操作</li><li><code>tryOnUnmounted</code> 安全的 onUnmounted。如果在组件生命周期内，调用 onUnmounted()，如果不是，不执行任何操作</li></ul><h2 id="watch" tabindex="-1">Watch <a class="header-anchor" href="#watch" aria-label="Permalink to &quot;Watch&quot;">​</a></h2><ul><li><code>watchArray</code> 监视数组的添加和移除</li><li><code>watchAtMost</code> watch 带有触发次数限制</li><li><code>watchDebounced</code> 延迟触发的监听器</li><li><code>watchThrottled</code> 节流式监视</li><li><code>watchDeep</code> 使用 { deep: true } 监听值的简写形式</li><li><code>watchIgnorable</code> 可忽略的 watch</li><li><code>watchImmediate</code> 使用 { immediate: true } 监听值的简写形式</li><li><code>watchOnce</code> 仅触发一次的 watch</li><li><code>watchPausable</code> 可暂停的 watch</li><li><code>watchTriggerable</code> 可手动触发的 watch</li><li><code>watchWithFilter</code> 带有额外 EventFilter 控制的 watch</li><li><code>until</code> 等待变化的一次性 Promise</li><li><code>whenever</code> 简写形式，监听值为真时触发</li></ul><h2 id="reactivity" tabindex="-1">Reactivity <a class="header-anchor" href="#reactivity" aria-label="Permalink to &quot;Reactivity&quot;">​</a></h2><ul><li><code>computedAsync</code> 用于异步函数的计算属性</li><li><code>computedEager</code> 即时计算的计算属性，没有延迟评估（Vue 3.4+ 可以直接使用 computed）</li><li><code>computedWithControl</code> 显式定义计算属性的依赖关系</li><li><code>createRef</code> 根据 deep 参数返回 deepRef 或 shallowRef</li><li><code>extendRef</code> 向 Ref 添加额外的属性</li><li><code>reactify</code> 将普通函数转换为响应式函数</li><li><code>reactifyObject</code> 将 reactify 应用于对象</li><li><code>reactiveComputed</code> 计算响应式对象。与 computed 返回一个 ref 不同，reactiveComputed 返回一个响应式对象</li><li><code>reactiveOmit</code> 从响应式对象中动态地排除字段</li><li><code>reactivePick</code> 从响应式对象中动态地选择字段</li><li><code>refAutoReset</code> 一个在一段时间后将重置为默认值的 ref</li><li><code>refDebounced</code> 对 ref 的更新进行防抖</li><li><code>refDefault</code> 将默认值应用于 ref</li><li><code>refThrottled</code> 限制 ref 值的变化频率</li><li><code>refWithControl</code> 对 ref 及其响应式进行细粒度控制</li><li><code>syncRef</code> 双向引用同步</li><li><code>syncRefs</code> 将目标引用与源引用保持同步</li><li><code>toReactive</code> 将 ref 转换为响应式对象。也可以创建一个&quot;可交换&quot;的响应式对象</li><li><code>toRef</code> 将值、ref 或 getter 规范化为 ref 或 computed</li><li><code>toRefs</code> 扩展了 toRefs，还接受对象引用的 refs</li></ul><h2 id="array" tabindex="-1">Array <a class="header-anchor" href="#array" aria-label="Permalink to &quot;Array&quot;">​</a></h2><ul><li><code>useArrayDifference</code> 响应式获取两个数组的差集</li><li><code>useArrayEvery</code> 响应式 Array.every</li><li><code>useArrayFilter</code> 响应式的 Array.filter</li><li><code>useArrayFind</code> 响应式 Array.find</li><li><code>useArrayFindIndex</code> 响应式 Array.findIndex</li><li><code>useArrayFindLast</code> 响应式 Array.findLast</li><li><code>useArrayIncludes</code> 响应式 Array.includes</li><li><code>useArrayJoin</code> 响应式 Array.join</li><li><code>useArrayMap</code> 响应式 Array.map</li><li><code>useArrayReduce</code> 响应式 Array.reduce</li><li><code>useArraySome</code> 响应式 Array.some</li><li><code>useArrayUnique</code> 响应式唯一数组</li><li><code>useSorted</code> 响应式排序数组</li></ul><h2 id="time" tabindex="-1">Time <a class="header-anchor" href="#time" aria-label="Permalink to &quot;Time&quot;">​</a></h2><ul><li><code>useCountdown</code> useIntervalFn 的包装器，提供倒计时功能</li><li><code>useDateFormat</code> 根据传入的字符串获取格式化日期，灵感来自 dayjs</li><li><code>useTimeAgo</code> 响应式的相对时间。当时间发生变化时，自动更新相对时间字符串</li></ul><h2 id="utilities" tabindex="-1">Utilities <a class="header-anchor" href="#utilities" aria-label="Permalink to &quot;Utilities&quot;">​</a></h2><ul><li><p><code>get</code> 用于访问 ref.value 的简写方式</p></li><li><p><code>set</code> ref.value = x 的简写</p></li><li><p><code>isDefined</code> 用于 Ref 的非空检查类型守卫</p></li><li><p><code>useCached</code> 使用自定义比较器缓存一个 ref</p></li><li><p><code>usePrevious</code> 保存 ref 的先前值</p></li><li><p><code>useCloned</code> 对 ref 进行响应式克隆。默认情况下，它使用 JSON.parse(JSON.stringify()) 进行克隆</p></li><li><p><code>useToNumber</code> 将字符串 ref 转换为数字</p></li><li><p><code>useToString</code> 将 ref 转换为字符串</p></li><li><p><code>useBase64</code> 响应式的 Base64 转换。 支持 plain text</p></li><li><p><code>useToggle</code> 一个带有实用功能的布尔切换器</p></li><li><p><code>makeDestructurable</code> 使对象和数组具有等价的解构性能。详见这篇博文获取更多详情。</p></li><li><p><code>createEventHook</code> 用于创建事件钩子的实用工具</p></li><li><p><code>createUnrefFn</code> 创建一个普通函数，接受 ref 和原始值作为参数</p></li><li><p><code>useAsyncQueue</code> 依次执行每个异步任务，并将当前任务的结果传递给下一个任务</p></li><li><p><code>useConfirmDialog</code> 创建事件钩子以支持模态框和确认对话框链</p></li><li><p><code>useCounter</code> 基础计数器，带有工具函数</p></li><li><p><code>useCycleList</code> 循环遍历一个项目列表</p></li><li><p><code>useDebounceFn</code> 延迟执行函数</p></li><li><p><code>useEventBus</code> 一个基本的事件总线</p></li><li><p><code>useMemoize</code> 根据参数缓存函数结果并保持其响应性。它也可以用于异步函数，并会重用现有的 Promise 以避免同时获取相同的数据</p></li><li><p><code>useOffsetPagination</code> 响应式的偏移分页</p></li><li><p><code>useStepper</code> 提供构建多步骤向导界面的辅助工具</p></li><li><p><code>useSupported</code> SSR 兼容性检测 isSupported</p></li><li><p><code>useThrottleFn</code> 节流执行函数。特别适用于限制事件处理程序在调整大小和滚动等事件上的执行频率</p></li><li><p><code>useTimeoutPoll</code> 使用超时来轮询某些内容。在最后一个任务完成后触发回调</p></li></ul>',25)])])}const h=o(l,[["render",r]]);export{m as __pageData,h as default};
